import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Menu, X, ArrowRight, ArrowUpRight, Star, Check, Plus, ChevronDown, ChevronRight,
  Sparkles, Calendar, Users, Image as ImageIcon, FileText, MessageSquare,
  CreditCard, Package, BarChart3, Megaphone, Heart, LayoutGrid,
  Clock, Shield, AlertCircle, TrendingUp, CheckCircle2, Globe,
  Inbox, Bell, Search, Settings as SettingsIcon,
  BookOpen, Code2, LifeBuoy, Newspaper, ArrowLeftRight, Building2, Briefcase, Activity,
  MapPin, Database, Plane, Droplet, Pause, Repeat, RefreshCw,
  Filter, ChevronLeft, AlertTriangle, RotateCcw, DollarSign, Lock,
  MoonStar, MoreHorizontal, ArchiveX, Coffee, Pin as PinIcon, Zap, Quote, PlayCircle,
} from 'lucide-react';

/* =========================================================================
   INKOS â LANDING V6 Â· "MANGOMINT-SATURATED"
   V5 stripped of tattoo SVG atmospheres. Mangomint-style organic blob layers
   replace them. Palette pushed louder/more saturated. Three-circles brand
   motif (artist Â· ink Â· skin) recurs as identity mark. All five Mangomint
   moves: gradient blobs, chunky cards, illustrated tiles, screenshots, photo bands.
   ========================================================================= */

const BRAND = {
  bone:       '#F7F7F5',
  boneCream:  '#FAFAF8',
  boneDeep:   '#EFEEEA',
  paper:      '#FCFBF7',
  white:      '#FFFFFF',

  onyx:       '#0F0F0F',
  ink:        '#1C1A18',
  smoke:      '#232120',
  char:       '#2A2725',
  coal:       '#3A3633',

  stoneDark:  '#4B4842',
  stone:      '#787774',
  stoneLight: '#9A9792',
  stoneFaint: '#6B6863',
  border:     '#E7E5E1',
  borderSoft: '#EFEEEA',
  borderInk:  '#3A3633',

  rust:       '#C8351F',      // pushed deeper/more saturated from #B23A2B
  rustBright: '#E8553F',      // brighter pop
  rustGlow:   '#F26B4D',      // hotter glow
  rustSoft:   '#FCE4DF',      // richer wash
  rustWash:   '#FBEFEB',      // a bit deeper than V5
  rustDeep:   '#7A1A0A',      // deeper deep

  sage:       '#5C8A55',      // brighter, more saturated from #6B8367
  sageSoft:   '#DFEAD9',      // deeper wash
  sageWash:   '#EEF5E9',      // brighter wash
  amber:      '#D89538',      // pushed warmer/brighter from #C28840
  amberSoft:  '#F8E4C2',      // richer wash
  amberWash:  '#FBEFD8',      // brighter wash
  crimson:    '#C73838',      // brighter from #B53B3B
  crimsonSoft:'#FEEBEB',

  warn:       '#C28840',
  success:    '#6B8367',
  danger:     '#B53B3B',
  dangerSoft: '#FEF2F2',
  dangerBorder: '#FCA5A5',
};

const FONT = {
  serif:  "'Instrument Serif', Georgia, serif",
  sans:   "'Inter', -apple-system, BlinkMacSystemFont, sans-serif",
  mono:   "'JetBrains Mono', 'IBM Plex Mono', Menlo, monospace",
};

/* Mangomint-inspired soft shadows â warm and friendly, not harsh */
const SHADOW = {
  soft:  '0 4px 16px -4px rgba(178,58,43,0.08), 0 2px 6px -2px rgba(15,15,15,0.04)',
  card:  '0 12px 32px -8px rgba(178,58,43,0.10), 0 4px 12px -4px rgba(15,15,15,0.06)',
  hero:  '0 32px 80px -16px rgba(178,58,43,0.18), 0 12px 32px -8px rgba(15,15,15,0.08)',
  glow:  '0 0 0 1px rgba(178,58,43,0.12), 0 16px 40px -8px rgba(178,58,43,0.20)',
};

/* The signature gradient washes â InkOS brand colors in Mangomint style */
const GRADIENT = {
  // hero atmosphere â soft rust glow on bone
  heroBloom: `radial-gradient(ellipse 80% 60% at 70% 20%, ${BRAND.rustWash} 0%, transparent 60%), radial-gradient(ellipse 60% 50% at 20% 80%, ${BRAND.amberWash} 0%, transparent 55%)`,
  // section warm wash
  sectionWarm: `linear-gradient(180deg, ${BRAND.bone} 0%, ${BRAND.rustWash} 50%, ${BRAND.bone} 100%)`,
  sectionCool: `linear-gradient(180deg, ${BRAND.boneCream} 0%, ${BRAND.sageWash} 50%, ${BRAND.boneCream} 100%)`,
  // card accent â for tinted backgrounds
  cardRust:  `linear-gradient(135deg, ${BRAND.rustWash} 0%, ${BRAND.bone} 100%)`,
  cardSage:  `linear-gradient(135deg, ${BRAND.sageWash} 0%, ${BRAND.bone} 100%)`,
  cardAmber: `linear-gradient(135deg, ${BRAND.amberWash} 0%, ${BRAND.bone} 100%)`,
  // signature corner glow (Mangomint move)
  cornerRust: `radial-gradient(circle at 0% 0%, ${BRAND.rustSoft} 0%, transparent 60%)`,
};

const fadeUp = {
  hidden:  { opacity: 0, y: 16 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.55, ease: [0.22, 1, 0.36, 1] } },
};
const stagger = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.06, delayChildren: 0.05 } },
};

/* âââââââââââââââââââââââââââââ MANGOMINT-STYLE LAYERS âââââââââââââââââââââââââââââ
   Three replacements for V5's tattoo SVG atmospheres. All organic gradient blobs
   in our saturated brand palette. Plus the three-circles brand motif. */

/* MangomintBlobs â organic radial gradient blobs in rust/amber/sage.
   Soft, multi-layered, low opacity, mix-blend-multiply.
   Variant prop: 'hero' | 'soft' | 'cta' */
function MangomintBlobs({ variant = 'soft' }) {
  const variants = {
    hero: [
      { cx: '85%', cy: '15%', size: 700, color: BRAND.rust,       opacity: 0.18 },
      { cx: '10%', cy: '70%', size: 600, color: BRAND.amber,      opacity: 0.15 },
      { cx: '60%', cy: '85%', size: 500, color: BRAND.rustBright, opacity: 0.12 },
      { cx: '40%', cy: '10%', size: 400, color: BRAND.sage,       opacity: 0.10 },
    ],
    soft: [
      { cx: '90%', cy: '20%', size: 500, color: BRAND.rust,  opacity: 0.10 },
      { cx: '15%', cy: '85%', size: 450, color: BRAND.amber, opacity: 0.10 },
      { cx: '50%', cy: '50%', size: 400, color: BRAND.sage,  opacity: 0.08 },
    ],
    cta: [
      { cx: '50%', cy: '0%',  size: 800, color: BRAND.rust,       opacity: 0.35 },
      { cx: '15%', cy: '90%', size: 600, color: BRAND.rustBright, opacity: 0.25 },
      { cx: '85%', cy: '90%', size: 600, color: BRAND.amber,      opacity: 0.20 },
    ],
  };
  const blobs = variants[variant] || variants.soft;

  return (
    <div aria-hidden="true" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none',
      mixBlendMode: variant === 'cta' ? 'screen' : 'multiply',
      overflow: 'hidden',
    }}>
      {blobs.map((b, i) => (
        <div key={i} style={{
          position: 'absolute',
          left: b.cx, top: b.cy,
          width: b.size, height: b.size,
          transform: 'translate(-50%, -50%)',
          background: `radial-gradient(circle, ${b.color} 0%, transparent 70%)`,
          opacity: b.opacity,
          filter: 'blur(40px)',
          borderRadius: '50%',
        }} />
      ))}
    </div>
  );
}

/* TriCircleMark â InkOS brand mark inspired by Mangomint's three-circles logo.
   Three intersecting circles representing artist Â· ink Â· skin.
   Used as a recurring brand motif: hero corner, footer, section transitions. */
function TriCircleMark({ size = 64, opacity = 1 }) {
  // Mangomint uses peach/lavender/magenta. We use rust/amber/sage for
  // artist (rust = the maker), ink (amber = the medium), skin (sage = the canvas).
  const w = size;
  const h = size * 0.92;
  return (
    <svg
      width={w} height={h} viewBox="0 0 64 59"
      xmlns="http://www.w3.org/2000/svg"
      style={{ opacity }}
      aria-hidden="true"
    >
      {/* Top-left: artist (rust) â quarter circle bottom-right */}
      <path
        d="M 30 0 a 30 30 0 0 0 -30 30 v -30 z"
        fill={BRAND.rust}
        transform="rotate(180 15 15)"
      />
      {/* Top-right: ink (amber) â full circle wedge */}
      <path
        d="M 34 0 v 30 a 30 30 0 0 0 30 -30 z"
        fill={BRAND.amber}
        transform="rotate(180 49 15)"
      />
      {/* Bottom: skin (sage) â interlocking arc */}
      <path
        d="M 17 30 a 15 15 0 1 0 30 0 a 15 15 0 1 0 -30 0 z"
        fill={BRAND.sage}
      />
    </svg>
  );
}

/* TriCircleMarkV2 â alternative cleaner version using simple circles */
function TriCircleMarkV2({ size = 80, opacity = 1, labels = false }) {
  const r = size * 0.28;
  const cx1 = size * 0.32;
  const cy1 = size * 0.32;
  const cx2 = size * 0.68;
  const cy2 = size * 0.32;
  const cx3 = size * 0.50;
  const cy3 = size * 0.68;

  return (
    <svg
      width={size} height={size} viewBox={`0 0 ${size} ${size}`}
      xmlns="http://www.w3.org/2000/svg"
      style={{ opacity }}
      aria-hidden="true"
    >
      {/* artist â rust */}
      <circle cx={cx1} cy={cy1} r={r} fill={BRAND.rust} fillOpacity="0.92" />
      {/* ink â amber */}
      <circle cx={cx2} cy={cy2} r={r} fill={BRAND.amber} fillOpacity="0.92" />
      {/* skin â sage */}
      <circle cx={cx3} cy={cy3} r={r} fill={BRAND.sage} fillOpacity="0.92" />
    </svg>
  );
}

/* PhotoBand â placeholder for a real tattoo studio photograph.
   Renders as a rich gradient with optional label, until real photos are dropped in. */
function PhotoBand({ height = 240, label, gradient, overlay = true }) {
  const grad = gradient || `linear-gradient(135deg, ${BRAND.rust} 0%, ${BRAND.rustGlow} 50%, ${BRAND.amber} 100%)`;
  return (
    <div style={{
      height, borderRadius: 16, overflow: 'hidden', position: 'relative',
      background: grad, boxShadow: SHADOW.card,
    }}>
      {/* texture overlay â looks like film grain on a real photo */}
      {overlay && (
        <div aria-hidden="true" style={{
          position: 'absolute', inset: 0,
          background: `url("data:image/svg+xml;charset=utf-8,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.4'/%3E%3C/svg%3E")`,
          opacity: 0.25, mixBlendMode: 'multiply',
        }} />
      )}
      {/* dark vignette at bottom for label legibility */}
      <div aria-hidden="true" style={{
        position: 'absolute', inset: 0,
        background: 'linear-gradient(180deg, transparent 50%, rgba(15,15,15,0.5) 100%)',
      }} />
      {label && (
        <div style={{
          position: 'absolute', bottom: 16, left: 18, right: 18,
          fontFamily: FONT.sans, fontSize: 13, fontWeight: 500,
          color: BRAND.bone, letterSpacing: '-0.005em',
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        }}>
          <span>{label}</span>
          <span style={{
            fontFamily: FONT.mono, fontSize: 10, opacity: 0.7,
            padding: '3px 8px', borderRadius: 100,
            background: 'rgba(247,247,245,0.15)',
            backdropFilter: 'blur(4px)',
          }}>PHOTO</span>
        </div>
      )}
    </div>
  );
}

/* âââââââââââââââââââââââââââââ REUSABLE BLOCKS âââââââââââââââââââââââââââââ  */

function SectionEyebrow({ label, dark = false, accent = 'rust' }) {
  const accentColors = {
    rust:  dark ? BRAND.rustBright : BRAND.rust,
    sage:  BRAND.sage,
    amber: BRAND.amber,
  };
  return (
    <div style={{
      display: 'inline-flex', alignItems: 'center', gap: 8,
      padding: '6px 14px', borderRadius: 100,
      background: dark ? 'rgba(247,247,245,0.08)' : BRAND.white,
      border: dark ? 'none' : `1px solid ${BRAND.border}`,
      fontFamily: FONT.sans, fontSize: 12, fontWeight: 500,
      color: dark ? BRAND.stoneLight : BRAND.stoneDark,
      letterSpacing: '0.02em', marginBottom: 22,
      boxShadow: dark ? 'none' : '0 1px 2px rgba(15,15,15,0.04)',
    }}>
      <span style={{
        width: 6, height: 6, borderRadius: 100,
        background: accentColors[accent],
      }} />
      {label}
    </div>
  );
}

function SectionHeading({ children, dark = false, size = 'md' }) {
  const sizes = {
    sm: 'clamp(28px, 3.4vw, 38px)',
    md: 'clamp(34px, 4.2vw, 50px)',
    lg: 'clamp(42px, 5.2vw, 64px)',
  };
  return (
    <h2 style={{
      fontFamily: FONT.sans, fontSize: sizes[size],
      lineHeight: 1.08, letterSpacing: '-0.025em',
      color: dark ? BRAND.bone : BRAND.onyx,
      fontWeight: 600, marginBottom: 18,
      maxWidth: 760,
    }}>{children}</h2>
  );
}

function SectionSubhead({ children, dark = false, max = 600 }) {
  return (
    <p style={{
      fontFamily: FONT.sans, fontSize: 17, fontWeight: 400,
      lineHeight: 1.6, color: dark ? BRAND.stoneLight : BRAND.stoneDark,
      maxWidth: max,
    }}>{children}</p>
