/* âââââââââââââââââââââââââââââ ROUTING âââââââââââââââââââââââââââââ */
function useRoute() {
  const [hash, setHash] = useState(() =>
    typeof window !== 'undefined' ? window.location.hash : ''
  );
  useEffect(() => {
    const onClick = (e) => {
      if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button !== 0) return;
      const link = e.target.closest && e.target.closest('a[href]');
      if (!link) return;
      const href = link.getAttribute('href');
      if (!href || !href.startsWith('#/')) return;
      e.preventDefault();
      setHash(href);
      try { window.history.replaceState(null, '', href); } catch (_) {}
      window.scrollTo({ top: 0, behavior: 'auto' });
      try { document.dispatchEvent(new CustomEvent('inkos:navigate', { detail: href })); } catch (_) {}
    };
    const onHashChange = () => {
      const next = window.location.hash;
      setHash(next);
      if (next.startsWith('#/')) window.scrollTo({ top: 0, behavior: 'auto' });
    };
    document.addEventListener('click', onClick);
    window.addEventListener('hashchange', onHashChange);
    return () => {
      document.removeEventListener('click', onClick);
      window.removeEventListener('hashchange', onHashChange);
    };
  }, []);
  return hash;
}
function currentPage(hash) {
  if (!hash || !hash.startsWith('#/')) return 'home';
  return hash.slice(2) || 'home';
}

function Nav() {
