          items: [
            { icon: Star, name: 'Solo artists', desc: 'One chair, full kit Â· $29/mo', href: '#pricing' },
            { icon: Users, name: 'Small studios', desc: '2â5 chairs Â· $59/mo', href: '#pricing' },
            { icon: LayoutGrid, name: 'Multi-chair shops', desc: '6+ chairs, multiple artists Â· $99/mo', href: '#pricing' },
