          fontFamily: FONT.sans,
          fontSize: 13,
          fontWeight: 500,
          color: BRAND.ink,
          lineHeight: 1.3,
        } as React.CSSProperties}>{item.name}</span>
        <span style={{
          fontFamily: FONT.sans,
          fontSize: 12,
          color: BRAND.stone,
          lineHeight: 1.4,
        } as React.CSSProperties}>{item.desc}</span>
      </span>
    </a>
  );
}

// ─── Mega menu panel ──────────────────────────────────────────────────────────

interface MegaPanelProps {
  item: NavItem;
  onMouseEnter: () => void;
  onMouseLeave: () => void;
}

function MegaPanel({ item, onMouseEnter, onMouseLeave }: MegaPanelProps) {
  const cols = megaGridCols(item.label);

  return (
    <div
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      style={{
        position: "absolute",
        top: "calc(100% + 8px)",
        left: "50%",
        transform: "translateX(-50%)",
        width: 1100,
        maxWidth: "calc(100vw - 48px)",
        background: BRAND.white,
        border: `1px solid ${BRAND.border}`,
        borderRadius: 16,
        boxShadow: "0 20px 60px -12px rgba(15,15,15,0.14), 0 4px 16px -4px rgba(15,15,15,0.06)",
        zIndex: 1000,
        overflow: "hidden",
      } as React.CSSProperties}
    >
      {/* Columns */}
      <div style={{
        display: "grid",
        gridTemplateColumns: `repeat(${cols}, 1fr)`,
        gap: 0,
        padding: "20px 20px 0",
      } as React.CSSProperties}>
        {item.columns?.map((col) => (
          <div key={col.title} style={{ padding: "0 12px 20px" } as React.CSSProperties}>
            <div style={{
              fontFamily: FONT.sans,
              fontSize: 11,
              fontWeight: 600,
              color: BRAND.stoneLight,
              letterSpacing: "0.08em",
              textTransform: "uppercase",
              marginBottom: 8,
              paddingLeft: 10,
            } as React.CSSProperties}>{col.title}</div>
            {col.items.map((it) => (
              <MegaItem key={it.name} item={it} />
            ))}
          </div>
        ))}
      </div>

      {/* Footer band */}
      {item.footer && (
        <div style={{
          borderTop: `1px solid ${BRAND.border}`,
          background: BRAND.bone,
          padding: "16px 32px",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 24,
        } as React.CSSProperties}>
          <div>
            <div style={{
              fontFamily: FONT.serif,
              fontSize: 16,
              color: BRAND.ink,
              marginBottom: 2,
            } as React.CSSProperties}>{item.footer.title}</div>
            <div style={{
              fontFamily: FONT.sans,
              fontSize: 12,
              color: BRAND.stone,
              lineHeight: 1.5,
            } as React.CSSProperties}>{item.footer.desc}</div>
          </div>
          <a
            href={item.footer.ctaHref}
            style={{
              flexShrink: 0,
              display: "inline-flex",
              alignItems: "center",
              gap: 6,
              padding: "9px 18px",
              borderRadius: 100,
              background: BRAND.onyx,
              color: BRAND.bone,
              fontFamily: FONT.sans,
              fontSize: 13,
              fontWeight: 500,
              textDecoration: "none",
              whiteSpace: "nowrap",
              transition: "background 0.15s",
            } as React.CSSProperties}
          >
            {item.footer.ctaLabel}
            <ArrowUpRight size={13} strokeWidth={2} />
          </a>
        </div>
      )}
    </div>
  );
}

// ─── Mobile accordion item ────────────────────────────────────────────────────

interface MobileNavItemProps {
  item: NavItem;
  expanded: boolean;
  onToggle: () => void;
}

function MobileNavItem({ item, expanded, onToggle }: MobileNavItemProps) {
  if (item.type === "link") {
    return (
      <a
        href={item.href}
        style={{
          display: "flex",
          alignItems: "center",
          gap: 8,
          padding: "14px 0",
          borderBottom: `1px solid ${BRAND.border}`,
          fontFamily: FONT.sans,
          fontSize: 16,
          fontWeight: 500,
          color: BRAND.ink,
          textDecoration: "none",
        } as React.CSSProperties}
      >
        {item.label}
        {item.dot && (
          <span style={{
            width: 6, height: 6, borderRadius: 100,
            background: BRAND.rust, display: "inline-block",
          } as React.CSSProperties} />
        )}
      </a>
    );
  }

  return (
    <div style={{ borderBottom: `1px solid ${BRAND.border}` } as React.CSSProperties}>
      <button
        onClick={onToggle}
        style={{
          width: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "14px 0",
          background: "none",
          border: "none",
          cursor: "pointer",
          fontFamily: FONT.sans,
          fontSize: 16,
          fontWeight: 500,
          color: BRAND.ink,
        } as React.CSSProperties}
      >
        {item.label}
        <ChevronDown
          size={16}
          strokeWidth={2}
          style={{
            color: BRAND.stone,
            transform: expanded ? "rotate(180deg)" : "rotate(0deg)",
            transition: "transform 0.2s",
          } as React.CSSProperties}
        />
      </button>
      {expanded && (
        <div style={{ paddingBottom: 12 } as React.CSSProperties}>
          {item.columns?.map((col) => (
            <div key={col.title} style={{ marginBottom: 16 } as React.CSSProperties}>
              <div style={{
                fontFamily: FONT.sans,
                fontSize: 11,
                fontWeight: 600,
                color: BRAND.stoneLight,
                letterSpacing: "0.08em",
                textTransform: "uppercase",
                marginBottom: 6,
                paddingLeft: 4,
              } as React.CSSProperties}>{col.title}</div>
              {col.items.map((it) => {
                const Icon = it.icon;
                return (
                  <a
                    key={it.name}
                    href={it.href}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 10,
                      padding: "7px 4px",
                      textDecoration: "none",
                    } as React.CSSProperties}
                  >
                    <Icon size={14} strokeWidth={1.6} style={{ color: BRAND.stone } as React.CSSProperties} />
                    <span style={{
                      fontFamily: FONT.sans,
                      fontSize: 14,
                      color: BRAND.ink,
                    } as React.CSSProperties}>{it.name}</span>
                  </a>
                );
              })}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ─── Nav ──────────────────────────────────────────────────────────────────────

export function Nav() {
  const [scrolled, setScrolled] = useState<boolean>(false);
  const [open, setOpen] = useState<boolean>(false);
  const [activeMenu, setActiveMenu] = useState<string | null>(null);
  const [mobileExpanded, setMobileExpanded] = useState<string | null>(null);
  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 24);
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const handleEnter = (label: string) => {
    if (closeTimer.current) clearTimeout(closeTimer.current);
    setActiveMenu(label);
  };

  const handleLeave = () => {
    closeTimer.current = setTimeout(() => setActiveMenu(null), 120);
  };

  const toggleMobile = (label: string) => {
    setMobileExpanded((prev) => (prev === label ? null : label));
  };

  // Pill shape + backdrop when scrolled
  const wrapperStyle: React.CSSProperties = scrolled
    ? {
        position: "fixed",
        top: 12,
        left: "50%",
        transform: "translateX(-50%)",
        width: "calc(100% - 48px)",
        maxWidth: 1200,
        zIndex: 900,
        transition: "all 0.3s ease",
      }
    : {
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        zIndex: 900,
        transition: "all 0.3s ease",
      };

  const barStyle: React.CSSProperties = scrolled
    ? {
        background: "rgba(252,251,247,0.92)",
        backdropFilter: "blur(16px)",
        WebkitBackdropFilter: "blur(16px)",
        borderRadius: 100,
        border: `1px solid ${BRAND.border}`,
        boxShadow: "0 4px 24px -4px rgba(15,15,15,0.10), 0 1px 4px -1px rgba(15,15,15,0.06)",
        padding: "0 20px",
        height: 52,
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
      }
    : {
        background: "rgba(252,251,247,0.80)",
        backdropFilter: "blur(12px)",
        WebkitBackdropFilter: "blur(12px)",
        borderBottom: `1px solid ${BRAND.border}`,
        padding: "0 40px",
        height: 64,
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        maxWidth: "100%",
      };

  return (
    <>
      <div style={wrapperStyle}>
        <div style={barStyle}>
          {/* Logo */}
          <a href="/" style={{ textDecoration: "none", display: "flex", alignItems: "center", gap: 9 } as React.CSSProperties}>
            <span style={{
              width: 28, height: 28,
              background: BRAND.onyx,
              borderRadius: 6,
              display: "flex", alignItems: "center", justifyContent: "center",
              flexShrink: 0,
            } as React.CSSProperties}>
              <span style={{
                fontFamily: FONT.serif,
                fontStyle: "italic",
                fontSize: 16,
                color: BRAND.bone,
                lineHeight: 1,
                userSelect: "none",
              } as React.CSSProperties}>i</span>
            </span>
            <span style={{
              fontFamily: FONT.sans,
              fontSize: 15,
              fontWeight: 600,
              color: BRAND.onyx,
              letterSpacing: "-0.01em",
            } as React.CSSProperties}>InkOS</span>
          </a>

          {/* Desktop nav items */}
          <nav
            className="inkos-nav-desktop"
            style={{
              display: "flex",
              alignItems: "center",
              gap: 2,
              position: "relative",
            } as React.CSSProperties}
          >
            {navItems.map((item) => {
              if (item.type === "link") {
                return (
                  <a
                    key={item.label}
                    href={item.href}
                    style={{
                      display: "inline-flex",
                      alignItems: "center",
                      gap: 5,
                      padding: "6px 12px",
                      borderRadius: 8,
                      fontFamily: FONT.sans,
                      fontSize: 14,
                      fontWeight: 450,
                      color: BRAND.ink,
                      textDecoration: "none",
                      transition: "background 0.12s",
                    } as React.CSSProperties}
                    onMouseEnter={(e) => {
                      (e.currentTarget as HTMLAnchorElement).style.background = BRAND.boneDeep;
                    }}
                    onMouseLeave={(e) => {
                      (e.currentTarget as HTMLAnchorElement).style.background = "transparent";
                    }}
                  >
                    {item.label}
                    {item.dot && (
                      <span style={{
                        width: 5, height: 5, borderRadius: 100,
                        background: BRAND.rust, display: "inline-block",
                      } as React.CSSProperties} />
                    )}
                  </a>
                );
              }

              // Mega menu trigger
              const isActive = activeMenu === item.label;
              return (
                <div
                  key={item.label}
                  style={{ position: "relative" } as React.CSSProperties}
                  onMouseEnter={() => handleEnter(item.label)}
                  onMouseLeave={handleLeave}
                >
                  <button
                    style={{
                      display: "inline-flex",
                      alignItems: "center",
                      gap: 4,
                      padding: "6px 12px",
                      borderRadius: 8,
                      background: isActive ? BRAND.boneDeep : "transparent",
                      border: "none",
                      cursor: "pointer",
                      fontFamily: FONT.sans,
                      fontSize: 14,
                      fontWeight: 450,
                      color: BRAND.ink,
                      transition: "background 0.12s",
                    } as React.CSSProperties}
                  >
                    {item.label}
                    <ChevronDown
                      size={13}
                      strokeWidth={2}
                      style={{
                        color: BRAND.stone,
                        transform: isActive ? "rotate(180deg)" : "rotate(0deg)",
                        transition: "transform 0.2s",
                      } as React.CSSProperties}
                    />
                  </button>

                  {isActive && (
                    <MegaPanel
                      item={item}
                      onMouseEnter={() => handleEnter(item.label)}
                      onMouseLeave={handleLeave}
                    />
                  )}
                </div>
              );
            })}
          </nav>

          {/* Right side */}
          <div style={{ display: "flex", alignItems: "center", gap: 8 } as React.CSSProperties}>
            <a
              href="#signin"
              className="inkos-nav-signin"
              style={{
                fontFamily: FONT.sans,
                fontSize: 14,
                fontWeight: 450,
                color: BRAND.stoneDark,
                textDecoration: "none",
                padding: "6px 12px",
                borderRadius: 8,
                transition: "color 0.12s",
              } as React.CSSProperties}
            >
              Sign in
            </a>
            <a
              href="#start"
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 6,
                padding: "8px 18px",
                borderRadius: 100,
                background: BRAND.onyx,
                color: BRAND.bone,
                fontFamily: FONT.sans,
                fontSize: 13,
                fontWeight: 500,
                textDecoration: "none",
                whiteSpace: "nowrap",
                transition: "background 0.15s",
              } as React.CSSProperties}
            >
              Start free
            </a>

            {/* Mobile burger */}
            <button
              className="inkos-nav-burger"
              onClick={() => setOpen((v) => !v)}
              style={{
                display: "none",
                alignItems: "center",
                justifyContent: "center",
                width: 36,
                height: 36,
                borderRadius: 8,
                background: BRAND.boneDeep,
                border: "none",
                cursor: "pointer",
              } as React.CSSProperties}
              aria-label={open ? "Close menu" : "Open menu"}
            >
              {open
                ? <X size={18} strokeWidth={2} style={{ color: BRAND.ink } as React.CSSProperties} />
                : <Menu size={18} strokeWidth={2} style={{ color: BRAND.ink } as React.CSSProperties} />
              }
            </button>
          </div>
        </div>

        {/* Mobile drawer */}
        {open && (
          <div
            className="inkos-nav-mobile"
            style={{
              display: "none", // shown via CSS at ≤768px
              marginTop: 8,
              background: BRAND.white,
              border: `1px solid ${BRAND.border}`,
              borderRadius: 16,
              padding: "8px 24px 24px",
              boxShadow: "0 12px 32px -8px rgba(15,15,15,0.12)",
            } as React.CSSProperties}
          >
            {navItems.map((item) => (
              <MobileNavItem
                key={item.label}
                item={item}
                expanded={mobileExpanded === item.label}
                onToggle={() => toggleMobile(item.label)}
              />
            ))}
            <div style={{ display: "flex", flexDirection: "column", gap: 10, marginTop: 20 } as React.CSSProperties}>
              <a
                href="#signin"
                style={{
                  display: "block",
                  textAlign: "center",
                  padding: "12px",
                  borderRadius: 10,
                  border: `1px solid ${BRAND.border}`,
                  fontFamily: FONT.sans,
                  fontSize: 15,
                  fontWeight: 500,
                  color: BRAND.ink,
                  textDecoration: "none",
                } as React.CSSProperties}
              >
                Sign in
              </a>
              <a
                href="#start"
                style={{
                  display: "block",
                  textAlign: "center",
                  padding: "12px",
                  borderRadius: 10,
                  background: BRAND.onyx,
                  fontFamily: FONT.sans,
                  fontSize: 15,
                  fontWeight: 500,
                  color: BRAND.bone,
                  textDecoration: "none",
                } as React.CSSProperties}
              >
                Start free
              </a>
            </div>
          </div>
        )}
      </div>

      {/* Spacer so content doesn't sit under fixed nav */}
      <div style={{ height: scrolled ? 0 : 64 } as React.CSSProperties} aria-hidden="true" />
    </>
  );
}

